"""Payroll summary from multi-site clock exports (see /app/docs)."""
import csv
import gzip
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        data = f.read()
    while data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8-sig")
    return text


def lines_of(text):
    out = []
    for ln in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if ln.strip() == "":
            continue
        out.append(ln)
    return out


def to_epoch(dt):
    """aware datetime -> integer seconds since epoch"""
    delta = dt.astimezone(UTC) - EPOCH
    return delta.days * 86400 + delta.seconds


def local_to_epoch(naive, zone, dst=None):
    """Wall-clock -> instant. dst: None (first occurrence), True/False to pick
    the occurrence that is on daylight/standard time when ambiguous."""
    d0 = naive.replace(tzinfo=zone, fold=0)
    d1 = naive.replace(tzinfo=zone, fold=1)
    if dst is None or d0.utcoffset() == d1.utcoffset():
        return to_epoch(d0)
    for d in (d0, d1):
        if bool(d.dst()) == dst:
            return to_epoch(d)
    return to_epoch(d0)


def standard_offset(zone):
    best = None
    for m in (1, 4, 7, 10):
        d = datetime(2026, m, 1, tzinfo=zone)
        if not d.dst():
            return d.utcoffset()
        best = d.utcoffset() - d.dst()
    return best


def parse_iso_offset(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


def split_header_name(s):
    return s.strip()


# ---------------------------------------------------------------- parsers
# each parser yields (punch_id, employee, direction('IN'/'OUT'), epoch)

def parse_abbr_csv(text, zone):
    header = None
    for ln in lines_of(text):
        row = next(csv.reader([ln]))
        row = [c.strip() for c in row]
        if "Badge" in row and "Punch" in row and "Time" in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        t = r["Time"].strip()
        parts = t.split()
        ampm = None
        if len(parts) == 2 and parts[1].upper() in ("AM", "PM"):
            ampm = parts[1].upper()
            t = parts[0]
        elif t[-2:].upper() in ("AM", "PM"):
            ampm = t[-2:].upper()
            t = t[:-2].strip()
        hh, mm, ss = (int(x) for x in t.split(":"))
        if ampm:
            hh = hh % 12
            if ampm == "PM":
                hh += 12
        mo, dd, yy = (int(x) for x in r["Date"].split("/"))
        naive = datetime(yy, mo, dd, hh, mm, ss)
        ab = r.get("Zone", "").strip().upper()
        dst = True if ab.endswith("DT") else (False if ab.endswith("ST") else None)
        yield (r["Record"].strip(), r["Badge"], r["Punch"].strip().upper(),
               local_to_epoch(naive, zone, dst))


def parse_epoch_jsonl(text, zone):
    schema = 1
    for ln in lines_of(text):
        obj = json.loads(ln)
        if not isinstance(obj, dict):
            continue
        if obj.get("heartbeat") is True:
            continue
        if "schema" in obj and "id" not in obj and "punch_id" not in obj:
            schema = int(obj["schema"])
            continue
        if schema == 2:
            if "punch_id" not in obj:
                continue
            pid = str(obj["punch_id"])
            emp = obj["employee"]
            d = str(obj["direction"]).upper()
            ep = int(obj["epoch_ms"]) // 1000
        else:
            if "id" not in obj:
                continue
            pid = str(obj["id"])
            emp = obj["emp"]
            d = str(obj["dir"]).upper()
            if "ts_ms" in obj:
                ep = int(obj["ts_ms"]) // 1000
            else:
                ep = int(obj["ts"])
        yield (pid, emp, d, ep)


def parse_offset_csv(text, zone):
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text))), delimiter=";"):
        r = {k.strip(): v for k, v in r.items()}
        ev = r["event"].strip().lower()
        d = "IN" if ev == "clock_in" else "OUT"
        yield (r["punch_id"], r["employee"], d, to_epoch(parse_iso_offset(r["timestamp"])))


def parse_legacy_fixed(text, zone):
    std = standard_offset(zone)
    off = std
    for ln in lines_of(text):
        t = ln[0]
        if t == "H":
            tail = ln[13:18].strip()
            if tail and tail[0] in "+-" and len(tail) == 5:
                sign = 1 if tail[0] == "+" else -1
                off = sign * timedelta(hours=int(tail[1:3]), minutes=int(tail[3:5]))
            else:
                off = std
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = "IN" if ln[15] == "I" else "OUT"
            dt = datetime.strptime(ln[16:30], "%Y%m%d%H%M%S")
            ep = to_epoch((dt - off).replace(tzinfo=UTC))
            yield (pid, "E" + badge, d, ep)


def parse_de_tsv(text, zone):
    header = None
    for ln in lines_of(text):
        row = [c.strip() for c in ln.split("\t")]
        if "Ausweis" in row and "Buchung" in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        dd, mo, yy = (int(x) for x in r["Datum"].split("."))
        parts = r["Uhrzeit"].split(":")
        hh, mm = int(parts[0]), int(parts[1])
        ss = int(parts[2]) if len(parts) > 2 else 0
        naive = datetime(yy, mo, dd, hh, mm, ss)
        z = r.get("Zeitzone", "").upper()
        dst = True if z == "MESZ" else (False if z == "MEZ" else None)
        d = "IN" if r["Buchung"].upper() == "K" else "OUT"
        yield (r["Nr"], r["Ausweis"], d, local_to_epoch(naive, zone, dst))


def parse_local_csv(text, zone):
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text)))):
        r = {k.strip(): v for k, v in r.items()}
        naive = datetime.strptime(r["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        yield (r["punch_ref"].strip(), r["employee_id"], r["direction"].strip().upper(),
               local_to_epoch(naive, zone, None))


def parse_local_jsonl(text, zone):
    for ln in lines_of(text):
        obj = json.loads(ln)
        p = obj.get("punch") if isinstance(obj, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        pid = p["id"]
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid)
        yield (pid, p["badge"], str(p["type"]).upper(), local_to_epoch(naive, zone, None))


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy_fixed,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


def list_files(d):
    out = []
    for root, _dirs, files in os.walk(d):
        for f in files:
            out.append(os.path.join(root, f))
    return sorted(out)


def read_csv_file(path):
    text = read_text(path)
    return list(csv.DictReader(io.StringIO("\n".join(lines_of(text)))))


# ---------------------------------------------------------------- main
def main(inp, outp):
    with open(os.path.join(inp, "period.json")) as f:
        period = json.load(f)
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso_offset(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_file(os.path.join(inp, "sites.csv")):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    for r in read_csv_file(os.path.join(inp, "employees.csv")):
        employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    for r in read_csv_file(os.path.join(inp, "rates.csv")):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Decimal(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site, id) -> [employee, dir, epoch]
    ever = set()
    for site, (zone, fmt) in sites.items():
        sdir = os.path.join(inp, "exports", site)
        if not os.path.isdir(sdir):
            continue
        parser = PARSERS[fmt]
        for path in list_files(sdir):
            text = read_text(path)
            for pid, emp, d, ep in parser(text, zone):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp.strip(), d, ep]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, "corrections")
    if os.path.isdir(cdir):
        for path in list_files(cdir):
            for r in read_csv_file(path):
                r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                if not r.get("correction_id"):
                    continue
                r["_issued"] = parse_iso_offset(r["issued_at"])
                corr.append(r)
    corr.sort(key=lambda r: (r["_issued"], r["correction_id"]))
    applied = 0
    for r in corr:
        if r["_issued"] > cutoff:
            continue
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = to_epoch(parse_iso_offset(r["time"]))
                applied += 1
        elif act == "add":
            if key not in ever and r["site"] in sites:
                punches[key] = [r["employee"], r["type"].upper(),
                                to_epoch(parse_iso_offset(r["time"]))]
                ever.add(key)
                applied += 1

    # group by employee (discarding unknown badges)
    per_emp = {}
    for (site, pid), (emp, d, ep) in punches.items():
        if emp not in employees:
            continue
        per_emp.setdefault(emp, []).append((ep, 0 if d == "OUT" else 1, site, pid, d))

    zones = {s: z for s, (z, _f) in sites.items()}

    def round_ep(ep, zone):
        off = zone.utcoffset(datetime.fromtimestamp(ep, UTC).astimezone(zone))
        offs = off.days * 86400 + off.seconds
        s = ep + offs
        r = (s + 180) // 360 * 360
        return ep + (r - s)

    def workday(ep, home):
        return datetime.fromtimestamp(ep, UTC).astimezone(home).date()

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}
    result = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tot_gross = Decimal(0)

    for emp, home_site in employees.items():
        home = zones[home_site]
        plist = sorted(per_emp.get(emp, []))
        kept = []
        last = None
        for ep, _o, site, pid, d in plist:
            rep = round_ep(ep, zones[site])
            if last is not None and last[4] == d and ep - last[0] <= 300:
                if pstart <= workday(rep, home) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            item = (ep, _o, site, pid, d, rep)
            kept.append(item)
            last = item

        shifts = []  # (in_rounded, out_rounded, site, workday)
        pending = None

        def count(kind, rep):
            if pstart <= workday(rep, home) <= pend:
                exc[kind] += 1

        for ep, _o, site, pid, d, rep in kept:
            if d == "IN":
                if pending is not None:
                    count("open_shifts", pending[5])
                pending = (ep, _o, site, pid, d, rep)
            else:
                if pending is not None and rep - pending[5] <= 16 * 3600:
                    shifts.append((pending[5], rep, pending[2], workday(pending[5], home)))
                    pending = None
                else:
                    if pending is not None:
                        count("open_shifts", pending[5])
                        pending = None
                    count("orphan_outs", rep)
        if pending is not None:
            count("open_shifts", pending[5])

        shifts = [s for s in shifts if pstart <= s[3] <= pend]
        shifts.sort(key=lambda s: (s[0], s[1]))

        day_cum = {}
        week_cum = {}
        paid_sum = ot_sum = night_sum = 0
        gross = Decimal(0)
        for rin, rout, site, wd in shifts:
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = night_minutes(rin, rout, zones[site])
            night = min(night, paid)
            before = day_cum.get(wd, 0)
            after = before + paid
            day_cum[wd] = after
            daily_ot = max(0, after - 480) - max(0, before - 480)
            nonot = paid - daily_ot
            wk = wd - timedelta(days=wd.weekday())
            wb = week_cum.get(wk, 0)
            wa = wb + nonot
            week_cum[wk] = wa
            weekly_ot = max(0, wa - 2400) - max(0, wb - 2400)
            ot = daily_ot + weekly_ot
            reg = paid - ot
            rate = None
            for eff, rt in rates.get(emp, []):
                if eff <= wd:
                    rate = rt
            if rate is None:
                rate = Decimal(0)
            pay = rate * (Decimal(reg) + Decimal("1.5") * ot) / 60 \
                + rate * Decimal("0.15") * night / 60
            gross += pay
            paid_sum += paid
            ot_sum += ot
            night_sum += night
        g = gross.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        result[emp] = {"shifts": len(shifts), "paid_minutes": paid_sum,
                       "overtime_minutes": ot_sum, "night_minutes": night_sum,
                       "gross": format(g, "f")}
        tot["shifts"] += len(shifts)
        tot["paid_minutes"] += paid_sum
        tot["overtime_minutes"] += ot_sum
        tot["night_minutes"] += night_sum
        tot_gross += g

    exc["corrections_applied"] = applied
    tot["gross"] = format(tot_gross.quantize(Decimal("0.01")), "f")
    out = {"period": {"start": period["start"], "end": period["end"]},
           "employees": result, "exceptions": exc, "totals": tot}
    os.makedirs(os.path.dirname(os.path.abspath(outp)), exist_ok=True)
    with open(outp, "w") as f:
        json.dump(out, f, indent=1, sort_keys=True)


def night_minutes(rin, rout, zone):
    """Minutes in [rin, rout) between 22:00 and 06:00 local time of zone."""
    n = 0
    t = rin
    cache_off = None
    cache_until = -1
    while t < rout:
        if t >= cache_until:
            dt = datetime.fromtimestamp(t, UTC).astimezone(zone)
            o = dt.utcoffset()
            cache_off = o.days * 86400 + o.seconds
            cache_until = t + 1800  # offsets change at most once in a few hours; refresh
        loc = (t + cache_off) % 86400
        if loc < 6 * 3600 or loc >= 22 * 3600:
            n += 1
        t += 60
    return n


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
